INSERT INTO public.about_page (id, mission, vision, title, content, images, created_at, updated_at) VALUES (2, 'Çiftçilerimize en yenilikçi tarım teknolojilerini ve en kaliteli ürünleri sunarak, onların verimliliğini ve gelirini artırmak. Sürdürülebilir tarım uygulamalarını yaygınlaştırarak hem toprağımızı korumak hem de gelecek nesillere daha verimli araziler bırakmak en temel amacımızdır.', 'Türkiye''nin fındık ve tarım sektöründe, teknoloji kullanımı, danışmanlık hizmetleri ve ürün kalitesiyle referans gösterilen lider bir marka olmak. Tarımda dijital dönüşüme öncülük ederek, sektörü geleceğe taşımak.', NULL, 'AKAYDIN TARIM, 2023 yılında, ömrünü fındık üretimine adamış olan Aydın Ak tarafından kurulmuştur. Kurucumuz Aydın Ak, yılların getirdiği deneyimi ve geleneksel üretim bilgisini, modern tarım teknolojileriyle birleştirerek sektöre yenilikçi bir soluk kazandırmayı hedeflemiştir.
