INSERT INTO public.services (id, title, description, icon_name, image_url, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES (16, 'Fındık Üretimi Danışmanlığı', 'Modern tarım teknikleri ve uzman ekibimizle verimliliğinizi artırıyoruz. Toprak analizinden hasat planlamasına kadar yanınızdayız.', 'leaf', '/akaydin-tarim/akaydin/images/DRON.jpeg', 'Fındık Üretimi Danışmanlığı - Akaydin Tarım', 'Modern tarım teknikleri ve uzman ekibimizle fındık üretim verimliliğinizi artırıyoruz. Toprak analizi, gübreleme, budama ve hasat planlaması hizmetleri.', 'fındık üretimi, tarım danışmanlığı, toprak analizi, hasat planlaması, fındık yetiştirme', '2025-10-31 16:07:39', '2025-10-31 16:16:41');
INSERT INTO public.services (id, title, description, icon_name, image_url, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES (17, 'Fındık İşleme Hizmetleri', 'Son teknoloji makinelerimizle fındık kırma, kavurma ve vakumlu paketleme hizmetleri sunuyoruz. Ürününüzün değerini koruyoruz.', 'settings', '/akaydin-tarim/uploads/service/1761919091_5c3119074a561f76.jpg', 'Fındık İşleme Hizmetleri - Akaydin Tarım', 'Son teknoloji makinelerimizle fındık kırma, kavurma ve vakumlu paketleme hizmetleri. Ürününüzün kalitesini ve değerini koruyoruz.', 'fındık işleme, fındık kırma, fındık kavurma, vakumlu paketleme, fındık paketleme', '2025-10-31 16:07:50', '2025-10-31 16:58:11');
INSERT INTO public.services (id, title, description, icon_name, image_url, seo_title, seo_description, seo_keywords, created_at, updated_at) VALUES (19, 'Organomineral Gübre Bayiliği', 'Toprağınızın ihtiyacı olan zengin içerikli, yüksek kaliteli organomineral gübre çeşitlerimizle fındık bahçenizi canlandırın.', 'package', '/akaydin-tarim/uploads/service/1761917531_3382cdbd50dbfa65.jpg', 'Organomineral Gübre Bayiliği - Akaydin Tarım', 'Zengin içerikli, yüksek kaliteli organomineral gübre çeşitlerimizle toprağınızı besleyin. Fındık bahçenizin verimi için güvenilir çözüm.', 'organomineral gübre, toprak gübresi, fındık gübresi, tarım gübresi, organik gübre', '2025-10-31 16:08:08', '2025-10-31 16:32:11');
